import streamlit as st
import pickle
import base64
import pandas as pd

MODEL_B64 = ""
model = pickle.loads(base64.b64decode(MODEL_B64))

st.title("Starbucks Food Type Predictor")
st.write("Nutrition values daalein, model batayega ke item kis type ka hai.")

calories = st.number_input("Calories", min_value=0, max_value=1000, value=300)
fat = st.number_input("Fat (g)", min_value=0.0, max_value=100.0, value=10.0)
carb = st.number_input("Carbs (g)", min_value=0, max_value=200, value=40)
fiber = st.number_input("Fiber (g)", min_value=0, max_value=50, value=2)
protein = st.number_input("Protein (g)", min_value=0, max_value=100, value=8)

if st.button("Predict"):
    data = pd.DataFrame(
        [[calories, fat, carb, fiber, protein]],
        columns=["calories", "fat", "carb", "fiber", "protein"],
    )
    result = model.predict(data)[0]
    st.success(f"Predicted type: {result}")
